@Controller
public class UserGraphQLController {

    private final UserService userService;
    private final OrderDataLoader orderDataLoader;

    public UserGraphQLController(UserService userService, OrderDataLoader orderDataLoader) {
        this.userService = userService;
        this.orderDataLoader = orderDataLoader;
    }

    @QueryMapping
    public User userById(@Argument Long id) {
        return userService.findById(id);
    }

    @SchemaMapping(typeName = "User", field = "orders")
    public CompletableFuture<List<Order>> getOrders(User user, DataFetchingEnvironment environment) {
        // Uses DataLoader to batch and cache downstream calls, solving the N+1 problem
        return orderDataLoader.load(user.getId());
    }
}
